// Its evaluation has effects (a timer), so the island loads eagerly.
const seenMode = process.env.ISLAND_MODE;
setTimeout(() => {}, 0);
exports.startServer = async function startServer(opts) {
  if (opts.port < 0) throw new Error(`bad port ${opts.port}`);
  return `started ${opts.name} on ${opts.port} (startkit saw ISLAND_MODE=${seenMode}, now ${process.env.ISLAND_MODE})`;
};
exports.version = "1.0.0";
